const AppDialog=(()=>{let resolve=null;function finish(value){const modal=document.getElementById('appDialog');modal.close();const callback=resolve;resolve=null;if(callback)callback(value);}function open(message,withInput){if(resolve)return Promise.resolve(null);const modal=document.getElementById('appDialog');document.getElementById('dialogMessage').textContent=message;const input=document.getElementById('dialogInput');input.hidden=!withInput;input.value='';document.getElementById('dialogInputLabel').hidden=!withInput;modal.showModal();if(withInput)input.focus();else document.getElementById('dialogOK').focus();return new Promise(done=>resolve=done);}function bind(){const modal=document.getElementById('appDialog');document.getElementById('dialogOK').onclick=()=>{const input=document.getElementById('dialogInput');finish(input.hidden?true:input.value);};document.getElementById('dialogCancel').onclick=()=>finish(null);modal.addEventListener('cancel',event=>{event.preventDefault();finish(null);});}return {bind,ask:message=>open(message,true),confirm:message=>open(message,false)};})();
